BEGIN TRANSACTION READ ONLY; SET LOCAL statement_timeout = '10s'; SET LOCAL lock_timeout = '2s'; SELECT n.nspname AS schema_name, t.typname, e.enumsortorder, e.enumlabel FROM pg_catalog.pg_type t JOIN pg_catalog.pg_namespace n ON n.oid = t.typnamespace JOIN pg_catalog.pg_enum e ON e.enumtypid = t.oid WHERE n.nspname = 'storage' AND t.typname = 'buckettype' ORDER BY e.enumsortorder; ROLLBACK;
